// Theme Atelier catalog: reads the official theme tokens and default atmosphere layers straight from the CSS that
// renders them, so the editor always starts from exactly what Muse shows. Run after changing app/themes.css,
// app/atmosphere.css or components/DiscoAtmosphere.css:  node scripts/generate-atelier-catalog.mjs
// tests/atelier.test.mjs fails if the generated file is stale.
import {readFileSync,writeFileSync} from 'node:fs';
import {fileURLToPath} from 'node:url';
import {dirname,join} from 'node:path';

const root=join(dirname(fileURLToPath(import.meta.url)),'..');
const read=path=>readFileSync(join(root,path),'utf8');
const squash=value=>value.replace(/\s+/g,' ').trim();

export function buildCatalog(){
 const themes=read('app/themes.css'),atmosphere=read('app/atmosphere.css'),disco=read('components/DiscoAtmosphere.css');
 const tokens={};
 for(const match of themes.matchAll(/:root\[data-theme="([^"]+)"\]\s*\{([^}]*)\}/g)){
  const values={};
  for(const [,name,value] of match[2].matchAll(/(--[\w-]+)\s*:\s*([^;]+);/g))values[name]=squash(value);
  tokens[match[1]]=values;
 }
 const block=(css,selector)=>{const start=css.indexOf(selector);if(start<0)throw Error(`missing ${selector}`);const open=css.indexOf('{',start),close=css.indexOf('}',open);return css.slice(open+1,close);};
 const variable=(body,name)=>{const match=body.match(new RegExp(`${name}:([\\s\\S]*?);\\n`));if(!match)throw Error(`missing ${name}`);return squash(match[1]);};
 const shared=block(atmosphere,':root {'),discoShared=block(disco,':root {'),discoTheme=block(atmosphere,':root[data-theme="disco-damage"] {');
 const planes={
  bloom:variable(shared,'--atmosphere-bloom-layers'),
  pool:variable(shared,'--atmosphere-pool-layers'),
  haze:variable(shared,'--atmosphere-haze-layers'),
  discoReflection:variable(shared,'--disco-reflection-layers'),
  discoSpill:variable(discoShared,'--disco-spill-layers'),
  discoCaustic:variable(discoShared,'--disco-caustic-layers'),
  discoPool:squash(discoTheme.replace(/^\s*--atmosphere-pool-layers:/,'').replace(/;\s*$/,'')),
 };
 return {tokens,planes};
}

export function renderCatalog(){
 const {tokens,planes}=buildCatalog();
 return `// Generated by scripts/generate-atelier-catalog.mjs from app/themes.css and the atmosphere stylesheets. Do not edit.
export const officialTokenValues:Record<string,Record<string,string>>=${JSON.stringify(tokens,null,1)};
export const defaultPlaneSources=${JSON.stringify(planes,null,1)} as const;
`;
}

if(process.argv[1]===fileURLToPath(import.meta.url)){
 writeFileSync(join(root,'lib/atelier/catalog.generated.ts'),renderCatalog());
 console.log('wrote lib/atelier/catalog.generated.ts');
}
